+import type { Todo } from '../../lib/todos';
+
+/** RFC 4180: quote fields containing a comma, a quote or a newline, doubling inner quotes. */
+export function csvField(value: string): string {
+  const needsQuotes = value.includes(',') || value.includes('"') || value.includes('\n');
+  return needsQuotes ? '"' + value.replace(/"/g, '""') + '"' : value;
+}
+
+export function toCsv(todos: Todo[]): string {
+  const header = 'id,title,done';
+  const rows = todos.map((t) => [t.id, csvField(t.title), String(t.done)].join(','));
+  return [header, ...rows].join('\n');
+}
+
+export function downloadCsv(todos: Todo[]): void {
+  const blob = new Blob([toCsv(todos)], { type: 'text/csv;charset=utf-8' });
+  const url = URL.createObjectURL(blob);
+  const link = document.createElement('a');
+  link.href = url;
+  link.download = 'sky-todo.csv';
+  link.click();
+  URL.revokeObjectURL(url);
+}
