+import { describe, expect, test } from 'bun:test';
+import { csvField, toCsv } from './index';
+
+describe('csv export', () => {
+  test('escapes a comma and a double quote', () => {
+    expect(csvField('buy milk, then say "hi"')).toBe('"buy milk, then say ""hi"""');
+  });
+
+  test('writes a header row and one row per todo', () => {
+    const csv = toCsv([{ id: 1, title: 'a, b', done: false } as never]);
+    expect(csv.split('\n')).toHaveLength(2);
+    expect(csv.split('\n')[0]).toBe('id,title,done');
+  });
+
+  test('leaves a plain title unquoted', () => {
+    expect(csvField('buy milk')).toBe('buy milk');
+  });
+});
